#include <cmath>
#include <iostream>

struct Vec2
{
    double x{};
    double y{};

    Vec2& operator+=(const Vec2& other) { x += other.x; y += other.y; return *this; }
    double length() const { return std::sqrt(x * x + y * y); }
    // TODO: normalized(), dot(), cross(), angle(), rotated(radians)
};

Vec2 operator+(Vec2 a, const Vec2& b) { return a += b; }
Vec2 operator*(const Vec2& v, double s) { return { v.x * s, v.y * s }; }
// TODO: -, /, unary -, ==

std::ostream& operator<<(std::ostream& out, const Vec2& v) { return out << '(' << v.x << ", " << v.y << ')'; }

int main()
{
    Vec2 position{ 0.0, 0.0 };
    Vec2 velocity{ 10.0, 15.0 };
    const Vec2 gravity{ 0.0, -9.81 };
    const double dt{ 0.1 };

    for (int step{ 0 }; step <= 30; ++step)
    {
        std::cout << "t=" << step * dt << "  " << position << '\n';
        // TODO: velocity changes by gravity * dt, position changes by velocity * dt
    }
    return 0;
}
